"""Generate shared version-four homepage starters; all photographs bind to Site-owned media."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
EMPTY='00000000-0000-0000-0000-000000000000'
def node(id,kind,**props):return {'id':id,'type':kind,'props':props}
def title(id,text):return node(id,'headline',text=text,level=2)
def text(id,value):return node(id,'editor',html=f'<p>{value}</p>')
def button(id,label,href):return node(id,'button',label=label,href=href,variant='outline')
def row(id,columns,ratios=None,**style):return {'id':id,'type':'section','ratios':ratios or ([100] if len(columns)==1 else [1,1,1] if len(columns)==3 else [50,50]),'columns':[{'id':f'{id}-column-{i}','type':'column','children':children} for i,children in enumerate(columns)],'style':{'content_width':'wide','padding':'lg','gap':'lg',**style},'responsive':{'mobile':{'stack':True,'gap':'md'}}}
def hero(id,heading,copy,href,mode='split'):
 return node(id,'hero_image',asset_id=EMPTY,alt='Choose an approved Site photograph',title=heading,text=copy,layout=mode,height='medium',mask='curve',actions=[{'id':id+'-action','label':'Explore opportunities','href':href}])
def build(code,label,college=False):
 prefix='college' if college else 'university'
 hero_nodes=[hero(prefix+'-hero-learn','Ideas that shape a better future','Discover learning, research and a community committed to public service.','#opportunities'),hero(prefix+'-hero-research','Discover. Collaborate. Make an impact.','Connect with our academic community and explore our work.','#research')]
 for item in hero_nodes:item['style']={'background':'navy','text_color':'inverse'}
 campus_nodes=[hero(prefix+'-campus-life','A place to belong','Explore student life, academic facilities and opportunities to connect.','#contact'),hero(prefix+'-campus-research','Knowledge in action','Meet the people and projects shaping our community.','#research','split_reverse')]
 rows=[
 row(prefix+'-hero',[[node(prefix+'-hero-carousel','layout_slider',items=[{'id':h['id']+'-slide','children':[h]} for h in hero_nodes])]],content_width='full',padding='none'),
 row(prefix+'-impact-title',[[title(prefix+'-impact-heading','Learning with purpose'),text(prefix+'-impact-intro','Education, discovery and service connect our community.')]]),
 row(prefix+'-impact',[[node(prefix+'-learn-icon','icon',icon='school',label='Education'),title(prefix+'-learn-title','Learn'),text(prefix+'-learn-text','Explore academic pathways and develop practical knowledge.')],[node(prefix+'-research-icon','icon',icon='book',label='Research'),title(prefix+'-research-title','Discover'),text(prefix+'-research-text','Connect ideas and collaborate on meaningful research.')],[node(prefix+'-community-icon','icon',icon='location',label='Community'),title(prefix+'-community-title','Connect'),text(prefix+'-community-text','Work together to serve our university and wider community.')]],background='mist',radius='lg'),
 row(prefix+'-quick',[[node(prefix+'-quick-anchor','menu_anchor',anchor='opportunities'),title(prefix+'-quick-title','Explore your opportunities'),node(prefix+'-quick-links','button_grid',items=[{'id':prefix+'-quick-news','label':'Latest news','href':'/posts'},{'id':prefix+'-quick-life','label':'Campus life','href':'#campus-life'},{'id':prefix+'-quick-research','label':'Research','href':'#research'},{'id':prefix+'-quick-contact','label':'Contact','href':'#contact'}])]]),
 row(prefix+'-campus',[[node(prefix+'-campus-anchor','menu_anchor',anchor='campus-life'),node(prefix+'-campus-carousel','layout_slider',items=[{'id':h['id']+'-slide','children':[h]} for h in campus_nodes])]],content_width='full',padding='none',background='mist'),
 row(prefix+'-news',[[title(prefix+'-news-title','Latest news'),text(prefix+'-news-intro','Updates from this Site, published by our editorial team.'),node(prefix+'-news-grid','loop_grid',source='posts',limit=4,presentation='featured'),button(prefix+'-news-more','View all news','/posts')]]),
 row(prefix+'-research',[[node(prefix+'-research-anchor','menu_anchor',anchor='research'),title(prefix+'-research-heading','Research and collaboration'),text(prefix+'-research-intro','Explore our research priorities and find opportunities to work together.')],[node(prefix+'-facilities','tabs',items=[{'id':prefix+'-tab-programs','title':'Academic programs','text':'Use this space to describe approved academic pathways and entry information.'},{'id':prefix+'-tab-facilities','title':'Facilities','text':'Describe your Site facilities, libraries and learning spaces.'},{'id':prefix+'-tab-support','title':'Student support','text':'Describe the support available to students and the community.'}])]],ratios=[60,40],background='mist',radius='lg'),
 row(prefix+'-partners',[[title(prefix+'-partners-title','Partnership and collaboration'),node(prefix+'-partners-carousel','anything_carousel',items=[{'id':prefix+'-partner-academic','children':[title(prefix+'-partner-academic-title','Academic collaboration'),text(prefix+'-partner-academic-text','Replace this introduction with approved partner information and links.'),button(prefix+'-partner-academic-link','Discuss a partnership','#contact')]},{'id':prefix+'-partner-community','children':[title(prefix+'-partner-community-title','Community partnerships'),text(prefix+'-partner-community-text','Share the work your Site undertakes with its community.'),button(prefix+'-partner-community-link','Contact our team','#contact')]}])]],background='mist',radius='lg'),
 row(prefix+'-contact',[[node(prefix+'-contact-anchor','menu_anchor',anchor='contact'),title(prefix+'-contact-heading','Start a conversation'),text(prefix+'-contact-copy','Send an enquiry to our Site team.')],[node(prefix+'-contact-form','contact_form',form_code='homepage-enquiries',submit_label='Send enquiry')]],ratios=[40,60]),
 ]
 return {'manifest_version':1,'id':code,'version':4,'name':label,'description':f'A responsive {"college or department" if college else "university"} homepage with split-image carousels, highlights, campus panels, published news, partnerships and enquiries. Select this Site\'s images before applying.','required_modules':['PAGES','VISUAL_BUILDER'],'media_slots':[{'code':'hero','label':'Hero photograph','node_ids':[h['id'] for h in hero_nodes]},{'code':'campus','label':'Campus photograph','node_ids':[h['id'] for h in campus_nodes]}],'layout':{'schema_version':1,'settings':{'show_title':False,'content_width':'full'},'rows':rows}}
if __name__=='__main__':
 for code,label,college in [('university-main','University Main',False),('college-department','College/Department',True)]:
  path=ROOT/f'backend/apps/cms/schemas/homepage/{code}.json';path.write_text(json.dumps(build(code,label,college),indent=2)+'\n',encoding='utf-8')
